function base32(n: number) { const a = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567", x = rand(n); return [...x].map(v => a[v % 32]).join(""); }
function recovery() { const x = base32(10); return x.slice(0, 5) + "-" + x.slice(5); }
